# ══════════════════════════════════════════════════
#  DDD: Aggregate Root + Domain Events
# ══════════════════════════════════════════════════
from dataclasses import dataclass, field
from typing import List, Optional
from datetime import datetime
from abc import ABC
import uuid

# ─── Domain Event base ───
@dataclass(frozen=True)
class DomainEvent:
    """
    Something that HAPPENED in the domain.
    Past tense name: OrderPlaced, PaymentReceived, ItemShipped.
    Immutable — events cannot be changed after they happen!
    """
    event_id  : str = field(default_factory=lambda: str(uuid.uuid4()))
    occurred_at: str = field(
        default_factory=lambda: datetime.now().isoformat()
    )

    @property
    def event_name(self) -> str:
        return self.__class__.__name__

# ─── Specific Domain Events ───
@dataclass(frozen=True)
class OrderPlaced(DomainEvent):
    order_id   : str = ""
    customer_id: str = ""
    total_amount: float = 0.0
    item_count : int = 0

@dataclass(frozen=True)
class OrderItemAdded(DomainEvent):
    order_id   : str = ""
    product_id : str = ""
    product_name: str = ""
    quantity   : int = 0
    unit_price : float = 0.0

@dataclass(frozen=True)
class OrderConfirmed(DomainEvent):
    order_id   : str = ""
    customer_id: str = ""
    total      : float = 0.0

@dataclass(frozen=True)
class OrderCancelled(DomainEvent):
    order_id: str = ""
    reason  : str = ""

@dataclass(frozen=True)
class PaymentReceived(DomainEvent):
    order_id      : str = ""
    amount        : float = 0.0
    transaction_id: str = ""

@dataclass(frozen=True)
class InventoryReserved(DomainEvent):
    order_id  : str = ""
    product_id: str = ""
    quantity  : int = 0

# ─── Value Objects ───
@dataclass(frozen=True)
class Money:
    amount  : float
    currency: str = "INR"
    def __add__(self, other):
        return Money(self.amount + other.amount, self.currency)
    def __mul__(self, n):
        return Money(self.amount * n, self.currency)
    def __str__(self): return f"₹{self.amount:,.2f}"
    def __gt__(self, other): return self.amount > other.amount

@dataclass(frozen=True)
class OrderItem:
    """Value Object — an item in the order"""
    product_id  : str
    product_name: str
    quantity    : int
    unit_price  : Money

    def __post_init__(self):
        if self.quantity <= 0:
            raise ValueError("Quantity must be positive")

    @property
    def subtotal(self) -> Money:
        return self.unit_price * self.quantity

    def __str__(self):
        return (f"{self.product_name} × {self.quantity} "
                f"@ {self.unit_price} = {self.subtotal}")

# ─── Aggregate Root ───
class Order:
    """
    AGGREGATE ROOT: Order is the entry point for the Order aggregate.
    All changes to order items, status, etc. go THROUGH Order.
    Order OWNS its items — you never modify an item directly.
    Order is responsible for its OWN consistency rules.
    Order records DOMAIN EVENTS for every meaningful state change.
    """

    MAX_ITEMS         = 20
    MIN_ORDER_AMOUNT  = Money(100, "INR")

    def __init__(self, order_id: str, customer_id: str):
        # Identity
        self._id          = order_id
        self._customer_id = customer_id

        # State
        self._items       : List[OrderItem] = []
        self._status      = "draft"
        self._created_at  = datetime.now()

        # Domain Events (collected, dispatched later)
        self._events      : List[DomainEvent] = []

        # Record creation event
        self._record(OrderPlaced(
            order_id    = order_id,
            customer_id = customer_id,
            total_amount= 0.0,
            item_count  = 0
        ))

    # ─── Properties ───
    @property
    def id(self): return self._id

    @property
    def customer_id(self): return self._customer_id

    @property
    def status(self): return self._status

    @property
    def items(self) -> List[OrderItem]:
        return list(self._items)   # defensive copy!

    @property
    def total(self) -> Money:
        if not self._items:
            return Money(0)
        result = self._items[0].subtotal
        for item in self._items[1:]:
            result = result + item.subtotal
        return result

    @property
    def item_count(self) -> int:
        return sum(item.quantity for item in self._items)

    # ─── Domain Events ───
    @property
    def domain_events(self) -> List[DomainEvent]:
        return list(self._events)

    def clear_events(self):
        """Called after events are dispatched"""
        self._events.clear()

    def _record(self, event: DomainEvent):
        self._events.append(event)

    # ─── Business Logic (the real DDD!) ───
    def add_item(self, product_id: str, product_name: str,
                 quantity: int, unit_price: Money):
        """
        Business rule: cannot add items to confirmed/cancelled orders.
        Business rule: max 20 unique items per order.
        """
        self._guard_draft()
        if len(self._items) >= self.MAX_ITEMS:
            raise ValueError(
                f"Order cannot have more than {self.MAX_ITEMS} items"
            )

        # If item already exists, increase quantity
        for i, existing in enumerate(self._items):
            if existing.product_id == product_id:
                new_item = OrderItem(
                    product_id, product_name,
                    existing.quantity + quantity, unit_price
                )
                self._items[i] = new_item
                print(f"  📦 Updated: {new_item}")
                return

        # New item
        item = OrderItem(product_id, product_name, quantity, unit_price)
        self._items.append(item)
        print(f"  📦 Added: {item}")

        self._record(OrderItemAdded(
            order_id    = self._id,
            product_id  = product_id,
            product_name= product_name,
            quantity    = quantity,
            unit_price  = unit_price.amount
        ))

    def remove_item(self, product_id: str):
        self._guard_draft()
        original_count = len(self._items)
        self._items = [i for i in self._items
                       if i.product_id != product_id]
        if len(self._items) == original_count:
            raise ValueError(f"Item {product_id} not in order")
        print(f"  🗑️  Removed item {product_id}")

    def confirm(self):
        """
        Business rules:
        - Must be in draft state
        - Must have at least one item
        - Total must exceed minimum
        """
        self._guard_draft()
        if not self._items:
            raise ValueError("Cannot confirm empty order")
        if not (self.total > self.MIN_ORDER_AMOUNT):
            raise ValueError(
                f"Order total {self.total} below minimum "
                f"{self.MIN_ORDER_AMOUNT}"
            )

        self._status = "confirmed"
        print(f"  ✅ Order {self._id} confirmed: {self.total}")

        self._record(OrderConfirmed(
            order_id   = self._id,
            customer_id= self._customer_id,
            total      = self.total.amount
        ))

    def receive_payment(self, amount: Money,
                        transaction_id: str):
        """
        Business rule: payment must match order total exactly.
        """
        if self._status != "confirmed":
            raise ValueError(
                "Can only pay for confirmed orders"
            )
        if amount.amount != self.total.amount:
            raise ValueError(
                f"Payment {amount} doesn't match total {self.total}"
            )

        self._status = "paid"
        print(f"  💳 Payment received: {amount} (TXN: {transaction_id})")

        self._record(PaymentReceived(
            order_id      = self._id,
            amount        = amount.amount,
            transaction_id= transaction_id
        ))

    def cancel(self, reason: str):
        """Business rule: can only cancel draft or confirmed orders"""
        if self._status in ("paid", "shipped", "delivered"):
            raise ValueError(
                f"Cannot cancel order in '{self._status}' status"
            )
        self._status = "cancelled"
        print(f"  🚫 Order {self._id} cancelled: {reason}")

        self._record(OrderCancelled(
            order_id = self._id,
            reason   = reason
        ))

    def _guard_draft(self):
        if self._status != "draft":
            raise ValueError(
                f"Cannot modify order in '{self._status}' status"
            )

    def __repr__(self):
        return (f"Order({self._id[:8]}, {self._status}, "
                f"{len(self._items)} items, {self.total})")

# ─── Domain Event Dispatcher ───
class DomainEventDispatcher:
    """
    Collects domain events from aggregates and dispatches them
    to registered handlers (observers).
    """

    def __init__(self):
        self._handlers = {}

    def register(self, event_type: type, handler):
        self._handlers.setdefault(event_type, []).append(handler)
        print(f"  📡 Registered handler for {event_type.__name__}")

    def dispatch(self, aggregate):
        events = aggregate.domain_events
        for event in events:
            handlers = self._handlers.get(type(event), [])
            for handler in handlers:
                handler(event)
        aggregate.clear_events()
        return len(events)

# ─── Event Handlers (downstream effects) ───
def on_order_confirmed(event: OrderConfirmed):
    print(f"  📧 [EMAIL] Sending confirmation for order {event.order_id}")
    print(f"  📦 [INVENTORY] Reserving stock for order {event.order_id}")

def on_payment_received(event: PaymentReceived):
    print(f"  💳 [PAYMENT] Recording TXN {event.transaction_id}")
    print(f"  📊 [ANALYTICS] Revenue +₹{event.amount:,.2f}")

def on_order_cancelled(event: OrderCancelled):
    print(f"  🔔 [NOTIFY] Order {event.order_id} cancelled: {event.reason}")
    print(f"  📦 [INVENTORY] Releasing reserved stock")

# ─── Testing ───
print("=" * 55)
print("  DDD: Aggregate + Domain Events")
print("=" * 55)

# Setup dispatcher
dispatcher = DomainEventDispatcher()
dispatcher.register(OrderConfirmed,  on_order_confirmed)
dispatcher.register(PaymentReceived, on_payment_received)
dispatcher.register(OrderCancelled,  on_order_cancelled)

print("\n--- Building an Order ---")
order = Order("ORD-2026-001", "CUST-001")
order.add_item("P001", "MacBook Pro",  1, Money(185000))
order.add_item("P002", "Magic Mouse",  2, Money(6500))
order.add_item("P003", "USB-C Hub",    1, Money(3500))
print(f"\nOrder total: {order.total}")
print(f"Items: {order.item_count}")

print("\n--- Confirming Order ---")
order.confirm()

# Dispatch events (AFTER transaction completes)
count = dispatcher.dispatch(order)
print(f"\n  📣 Dispatched {count} domain events")

print("\n--- Payment ---")
order.receive_payment(Money(208000), "TXN-RZP-789")
dispatcher.dispatch(order)

print("\n--- Business Rule Violations ---")
order2 = Order("ORD-2026-002", "CUST-002")
try:
    order2.confirm()   # empty order!
except ValueError as e:
    print(f"  ❌ {e}")

order3 = Order("ORD-2026-003", "CUST-003")
order3.add_item("P001", "Laptop", 1, Money(75000))
order3.confirm()
try:
    order3.add_item("P002", "Mouse", 1, Money(1500))  # can't modify confirmed!
except ValueError as e:
    print(f"  ❌ {e}")

order3.cancel("Customer changed mind")
dispatcher.dispatch(order3)

try:
    order3.cancel("Again?")   # can't cancel twice!
except ValueError as e:
    print(f"  ❌ {e}")
```
